### FUNCION: connectColorPickerListener
```js
function connectColorPickerListener(tableBody) {
    const toolbar = document.getElementById('colorPickerToolbar');
    if (!toolbar || !document.getElementById('cellColorInput')) return;

    const colorInput = document.getElementById('cellColorInput');
    let activeCellId = null; // Almacena el ID de la celda actualmente seleccionada para colorear

    // 1. Escuchar clics en cualquier TD editable para seleccionar una celda
    tableBody.addEventListener('click', (e) => {
        const target = e.target.closest('[data-cell]');
        if (target) {
            activeCellId = target.getAttribute('data-cell');
            // Resaltar visualmente la celda seleccionada (opcional, pero mejora UX)
            document.querySelectorAll('#spreadsheetTable td[contenteditable="true"]').forEach(td => {
                td.removeAttribute('data-highlight');
            });
            target.setAttribute('data-highlight', '');

        } else {
            activeCellId = null;
        }
    });

    // 2. Escuchar cambios en el input de color para aplicar el fondo a la celda activa
    colorInput.addEventListener('input', (e) => {
        const newColor = e.target.value;
        if (activeCellId) {
            setColorCell(activeCellId, newColor);
        } else {
            // Si no hay celda activa, se podría limpiar o informar al usuario
            console.warn("No cell selected to apply color.");
        }
    });
}
