function handleColumnControlClick(e) {
    const button = e.target.closest('button');
    if (!button) return;

    const colHeader = button.closest('.column-header');
    if (!colHeader) return;

    const colChar = colHeader.getAttribute('data-col-char');
    const action = button.getAttribute('data-action');

    if (action === 'clear-content') {
        clearColumnContent(colChar);
    } else if (action === 'set-background') {
        setBackgroundColor(colChar);
    } else if (action === 'delete-column') {
        if (confirm(`¿Está seguro de que desea eliminar la columna ${colChar}? Esta acción es irreversible.`)) {
            deleteColumn(colChar);
        }
    }
}

function conectar() {
    // 1. Event Listener para las celdas editables (Event Delegation en tbody)
    const tableBody = document.querySelector('#spreadsheetTable tbody');
    if (!tableBody) return;

    // Delegación de eventos para edición de celdas
    tableBody.addEventListener('focusout', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            handleCellChange(target);
        }
    });

    tableBody.addEventListener('keydown', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            if (e.key === 'Enter') {
                e.preventDefault(); 
                handleCellChange(target);
            }
        }
    });

    // 2. Event Listener para los controles de columna (Event Delegation en thead)
    const tableHeader = document.querySelector('#spreadsheetTable thead');
    if (!tableHeader) return;

    tableHeader.addEventListener('click', handleColumnControlClick);
}

// ===== ARRANQUE (lo pone el harness: no lo cambies) =====
function arrancar() { cargar(); conectar(); render(); }
if (document.readyState === "loading") document.addEventListener("DOMContentLoaded", arrancar); else arrancar();
