function deleteColumn(colChar) {
    if (!colChar || !COLS.includes(colChar)) return;

    // 1. Limpiar el estado de la columna seleccionada (Borrar contenido)
    for (let r = 1; r <= ROWS; r++) {
        const cellId = colChar + r;
        estado[cellId] = "";
    }

    // 2. Actualizar y Redibujar: Eliminar el elemento del DOM y ajustar los índices.
    // Nota: La eliminación real de una columna es compleja (reindexación de todas las referencias).
    // Aquí, simplemente removemos la columna visualmente y ajustamos COLS para futuras referencias,
    // manteniendo la estructura general intacta si no hay dependencias complejas en fórmulas.

    const colIndex = COLS.indexOf(colChar);
    if (colIndex === -1) return;

    // Remover el carácter de la lista global de columnas
    COLS.splice(colIndex, 1);

    // Reconstruir el DOM para eliminar visualmente la columna y reajustar anchos/posiciones
    const table = document.getElementById('spreadsheetTable');
    if (!table) return;

    let targetColHeader = table.querySelector(`th[data-col="${colChar}"]`);
    if (targetColHeader) {
        // Eliminar la cabecera de columna
        targetColHeader.remove();
    }

    // Recorrer las filas del cuerpo y eliminar el TD correspondiente
    const rows = table.querySelectorAll('tbody tr');
    rows.forEach(row => {
        let targetCell = row.querySelector(`td[data-cell^="${colChar}"]`);
        if (targetCell) {
            targetCell.remove();
        }
    });

    // Limpiar la selección visual y redibujar el resto de las celdas
    deseleccionarColumna();
    render(); 
}
