function conectar() {
    // 1. Setup Column Header Click Listeners (Delegation)
    const table = document.getElementById('spreadsheetTable');
    if (!table) return;

    const headerRow = table.querySelector('#spreadsheetTable thead tr');
    if (!headerRow) return;

    // Asumiendo que los <th> de las letras están directamente en el thead (después del row-label th).
    // Usaremos un selector general para hacerlos clickeables, pero debemos excluir el primer TH (row label corner).
    const columnHeaders = headerRow.querySelectorAll('th:not(:first-child)');

    columnHeaders.forEach(header => {
        // Añadir data attribute para identificar la columna y agregar listener
        if (!header.hasAttribute('data-col')) {
             // Determinamos la letra de la columna basada en el índice relativo (1, 2, 3...)
            const colIndex = Array.from(columnHeaders).indexOf(header);
            const colChar = COLS[colIndex];
            header.setAttribute('data-col', colChar);
        }

        // Agregar listener de clic para seleccionar la columna
        header.addEventListener('click', (e) => {
            selectColumn(e.currentTarget.getAttribute('data-col'));
        });
    });


    // 2. Evento de pérdida de foco (blur): Se dispara al hacer clic fuera o con Tab.
    const tableBody = document.querySelector('#spreadsheetTable tbody');
    if (!tableBody) return;

    tableBody.addEventListener('focusout', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            handleCellChange(target);
        }
    });

    // 3. Evento de pulsación de tecla (keydown): Para detectar Enter.
    tableBody.addEventListener('keydown', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            // Solo procesar si se presiona Enter y no estamos en un estado de edición especial
            if (e.key === 'Enter') {
                e.preventDefault(); // Previene el salto de línea por defecto en contenteditable
                handleCellChange(target);
            }
        }
    });
}
