function selectColumn(colChar) {
    if (!COLS.includes(colChar)) return;

    // 1. Desseleccionar cualquier otra columna y actualizar el DOM visualmente
    const header = document.querySelector(`th[data-col="${colChar}"]`);
    if (header) {
        deseleccionarColumna(); // Función auxiliar para limpiar la selección
        header.classList.add('selected-column');
        window._selectedColumn = colChar; 
    } else {
