function conectar() {
    const tableBody = document.querySelector('#spreadsheetTable tbody');
    const headerRow = document.querySelector('#spreadsheetTable thead tr');
    const contextMenu = document.getElementById('columnContextMenu');

    // --- Event Listener for Column Headers (A, B, C...) ---
    headerRow.querySelectorAll('.col-header').forEach(header => {
        // Detectar clic derecho para mostrar el menú de acciones
        header.addEventListener('contextmenu', function(e) {
            e.preventDefault(); // Prevenir el menú contextual nativo del navegador

            const colChar = this.getAttribute('data-column');
            if (!colChar) return;

            // 1. Establecer la columna seleccionada y actualizar el estado visual (si fuera necesario, aunque aquí solo usamos JS state)
            selectedColumn = colChar;

            // 2. Mostrar el menú contextual en la posición del header
            contextMenu.style.display = 'block';
            this.style.backgroundColor = '#d0eaff'; // Visual feedback for selection
        });

        // Detectar clic izquierdo para seleccionar la columna sin abrir el menú (o simplemente hacer que sea el foco)
        header.addEventListener('click', function(e) {
             if (!e.altKey && !e.ctrlKey) { // Solo si no se usa un modificador de tecla especial
                selectedColumn = this.getAttribute('data-column');
            }
        });
    });

    // --- Event Listener for Context Menu Actions ---
    contextMenu.addEventListener('click', (e) => {
        const action = e.target.dataset.action;
        if (!action) return;

        const colChar = selectedColumn;
        if (!colChar) {
            contextMenu.style.display = 'none';
            return;
        }

        // Ejecutar la acción seleccionada
        switch (action) {
            case 'clearColumn':
                clearColumn(colChar);
                break;
            case 'colorizeColumn':
                const color = document.getElementById('colorPicker').value;
                setBackgroundColor(colChar, color);
                break;
            case 'deleteColumn':
                if (confirm(`¿Está seguro de que desea borrar la columna ${colChar}? Esta acción es irreversible.`)) {
                    deleteColumn(colChar);
                }
                break;
        }
        // Ocultar el menú después de la acción
        contextMenu.style.display = 'none';
    });

    // --- Event Listener for Body Click (to close context menu) ---
    document.addEventListener('click', (e) => {
        if (!e.target.closest('.col-header') && !e.target.closest('#columnContextMenu')) {
             contextMenu.style.display = 'none';
             // Resetear el color de fondo del header seleccionado si se hace click en otro lugar
             document.querySelector('.col-header[data-column="' + selectedColumn + '"]')?.style.backgroundColor = '';
        }
    });

    // 1. Evento de pérdida de foco (blur): Se dispara al hacer clic fuera o con Tab.
    tableBody.addEventListener('focusout', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            handleCellChange(target);
        }
    });

    // 2. Evento de pulsación de tecla (keydown): Para detectar Enter.
    tableBody.addEventListener('keydown', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            // Solo procesar si se presiona Enter y no estamos en un estado de edición especial
            if (e.key === 'Enter') {
                e.preventDefault(); // Previene el salto de línea por defecto en contenteditable
                handleCellChange(target);
            }
        }
    });

    // Inicializar la selección si es necesario al arrancar, pero lo dejaremos simple para no romper nada.
}
