```js
function deleteColumn(colChar) {
    const newEstado = {};
    const deletedColIdPrefix = colChar;
    const columnsToRemove = [colChar]; // Solo la columna actual

    // 1. Actualizar el estado (eliminar todas las claves de esta columna)
    for (let r = 1; r <= ROWS; r++) {
        const cellId = deletedColIdPrefix + r;
        if (estado[cellId] !== undefined) {
            delete newEstado[cellId]; // Simplemente no incluirla en el nuevo estado
        }
    }

    // Reconstruir el estado, omitiendo la columna eliminada. Esto es complejo de hacer con un solo objeto global.
    // Dado que estamos limitados a manipular 'estado', la forma más segura es reescribirlo completamente para eliminar las claves.
    let tempEstado = {};
    for (const cellId in estado) {
        if (!cellId.startsWith(deletedColIdPrefix)) {
            tempEstado[cellId] = estado[cellId];
        }
    }
    estado = tempEstado;

    // 2. Actualizar el DOM (HTML) y los datos de la columna eliminada
    const tableBody = document.getElementById('spreadsheetTable');
    if (!tableBody) return;

    let cellsToRemove = [];
    for (let r = 1; r <= ROWS; r++) {
        cellsToRemove.push(document.querySelector(`td[data-cell="${deletedColIdPrefix}${r}"]`));
    }

    // Eliminar los TDs de las celdas y el TH del encabezado
    cellsToRemove.forEach(cell => cell && cell.remove());

    const header = document.querySelector(`.col-header[data-column="${colChar}"]`);
    if (header) {
        header.remove();
    }


    // 3. Ajustar las propiedades de ancho y el índice de todas las columnas restantes
    const remainingHeaders = Array.from(document.querySelectorAll('.col-header')).filter(h => h.getAttribute('data-column') !== colChar);
    remainingHeaders.forEach((h, index) => {
        // Reajustar anchos para que el espacio sea distribuido entre los restantes
        h.style.width = `calc(${100 / (COLS.length - 1)}%)`;
    });

    // Redibujar y limpiar selección
    selectedColumn = null;
    render(); // Esto redibuja las celdas, aunque no hay datos nuevos, es crucial para reajustar el layout.
}
