### FUNCION: deleteColumn
```js
/**
 * Elimina completamente una columna dada su letra.
 * 1. Actualiza el estado eliminando todas las referencias de la columna.
 * 2. Elimina los TD y TH correspondientes del DOM.
 * 3. Redibuja la hoja de cálculo.
 * @param {string} colChar - La letra de la columna a eliminar (ej: "A").
 */
function deleteColumn(colChar) {
    if (!colChar || !COLS.includes(colChar)) return;

    // 1. Actualizar el estado
    for (let r = 1; r <= ROWS; r++) {
        const cellId = colChar + r;
        delete estado[cellId];
    }

    // 2. Eliminar elementos del DOM
    // Eliminar TH de la cabecera
    const headerTh = document.querySelector(`th[data-column="${colChar}"]`);
    if (headerTh) {
        headerTh.remove();
    }

    // Eliminar todos los TD en el tbody para esa columna
    const columnCells = document.querySelectorAll(`td[data-cell^="${colChar}"]`);
    columnCells.forEach(cell => cell.remove());

    // 3. Redibujar la hoja de cálculo
    guardar();
    render();
}
