```js
/**
 * Maneja la selección de una fila, permitiendo acciones como borrar, limpiar o cambiar color.
 * @param {HTMLElement} rowLabelElement - El elemento que contiene el número de la fila (ej: '3').
 */
function handleRowSelect(rowLabelElement) {
    const rowIndex = parseInt(rowLabelElement.textContent);
    if (isNaN(rowIndex) || rowIndex < 1 || rowIndex > ROWS) return;

    // Mostrar un menú o botones contextuales para las acciones requeridas.
    // Como no podemos modificar la UI con complejidad, simularemos el contexto al hacer clic y añadir los controles temporalmente.
    const rowContainer = document.querySelector(`[data-row="${rowIndex}"]`);
    if (!rowContainer) return;

    // Crear un contenedor de control justo después del label si no existe
    let controlsContainer = rowLabelElement.nextElementSibling;
    if (!controlsContainer || !controlsContainer.classList.contains('row-controls')) {
        controlsContainer = document.createElement('div');
        controlsContainer.className = 'row-controls';
        // Añadir botones para las acciones requeridas (Borrar, Limpiar)
        controlsContainer.innerHTML = `
            <button class="action-btn" data-action="clear">Limpiar Fila</button>
            <button class="action-btn" data-action="delete">Borrar Fila</button>
        `;
        rowLabelElement.parentNode.insertBefore(controlsContainer, rowLabelElement.nextSibling);
    }

    // Agregar un listener temporal para los botones de control de la fila seleccionada
    const actionButtons = controlsContainer.querySelectorAll('.action-btn');
    actionButtons.forEach(button => {
        button.onclick = (e) => {
            const action = e.currentTarget.getAttribute('data-action');

            if (action === 'clear') {
                // 1. Limpiar contenido de todas las celdas
                for (let i = 0; i < COLS.length; i++) {
                    const colChar = COLS[i];
                    actualizarCelda(colChar + rowIndex, "");
                }
            } else if (action === 'delete') {
                // 2. Borrar la fila completa
                handleDeleteRow(rowIndex);
            }

            // Opcional: Desactivar botones después de usar
            actionButtons.forEach(b => b.disabled = true);
        };
    });
}

/**
 * Elimina una fila completa (datos y etiqueta) del estado y del DOM.
 * @param {number} rowIndex - El índice de la fila a borrar.
 */
function handleDeleteRow(rowIndex) {
    // 1. Borrar datos del estado
    for (let i = 0; i < COLS.length; i++) {
        const colChar = COLS[i];
        const cellId = colChar + rowIndex;
        if (estado.hasOwnProperty(cellId)) {
            delete estado[cellId];
        }
    }

    // 2. Borrar la fila del DOM (incluyendo el label y los TDs)
    const rowDataContainer = document.querySelector(`[data-row="${rowIndex}"]`);
    if (rowDataContainer) {
        rowDataContainer.remove(); // Elimina el tr de datos
    }

    // 3. Borrar la etiqueta de fila del DOM
    const labelElement = document.querySelector(`.row-label[data-row="${rowIndex}"]`);
    if (labelElement) {
         // También borramos los controles que agregamos temporalmente
        const controlsContainer = labelElement.nextElementSibling;
        if(controlsContainer && controlsContainer.classList.contains('row-controls')){
            controlsContainer.remove();
        }
        labelElement.remove();
    }

    guardar();
    render(); // Redibujar para limpiar cualquier estado residual y sincronizar.
}
