```js
function handleRowSelect(event) {
    const rowLabel = event.currentTarget;
    // Intentamos obtener el índice de la fila (ej: '3'). Usamos parseInt para seguridad.
    const rowIndexString = rowLabel.textContent.trim();
    const rowIndex = parseInt(rowIndexString, 10);

    if (isNaN(rowIndex)) {
        console.error("No se pudo determinar un índice de fila válido.");
        return;
    }

    // El índice del array es 0-based, pero los labels son 1-based.
    const rowElement = document.querySelector(`tbody tr:nth-child(${rowIndex})`);

    if (!rowElement) {
        console.error(`No se encontró la fila con el índice ${rowIndex}.`);
        return;
    }

    // Mostrar un menú o pedir confirmación para las acciones (simulando un control).
    let action = prompt(
        `¿Qué acción deseas realizar en la Fila ${rowIndex}? \n\nOpciones:\n1. Borrar contenido (Clear)\n2. Cambiar fondo a amarillo (Color)\n3. Eliminar fila (Delete)`
    );

    if (!action) return; // Usuario canceló

    const actionMap = {
        '1': 'clear',
        '2': 'color',
        '3': 'delete'
    };

    const selectedAction = actionMap[action] || null;

    if (selectedAction === 'clear') {
        // 1. Borrar contenido de todas las celdas
        rowElement.querySelectorAll('td').forEach(cell => {
            cell.textContent = '';
            cell.removeAttribute('style'); // Limpiamos estilos anteriores si los hay
        });
    } else if (selectedAction === 'color') {
        // 2. Cambiar color de fondo de todas las celdas
        rowElement.querySelectorAll('td').forEach(cell => {
            cell.style.backgroundColor = 'yellow';
        });
    } else if (selectedAction === 'delete') {
        // 3. Borrar la fila completa
        if (!confirm(`¿Estás seguro de que quieres eliminar completamente la Fila ${rowIndex}?`)) {
            return;
        }
        rowElement.remove();

        // Después de eliminar, necesitamos recalcular los índices visuales si es necesario,
        // pero por simplicidad y dado el scope del ejercicio, solo eliminamos el elemento DOM.
    }

    // Guardar estado (si se borró contenido o color) y redibujar para reflejar cambios estructurales/visuales.
    guardar();
    render();
}
