### ARCHIVO: script.js
```javascript
// DATOS GLOBALES Y ESTADO
let estado = {};
const MAX_ROWS = 20;
const MAX_COLS = 10; // A-J

/**
 * Inicializa el estado con valores vacíos para todas las celdas.
 */
function cargar() {
    estado = {};
    for (let i = 1; i <= MAX_ROWS; i++) {
        for (let j = 1; j <= MAX_COLS; j++) {
            const cellId = String.fromCharCode(64 + j) + i; // A1, B1, etc.
            estado[cellId] = '';
        }
    }
    console.log("Estado cargado y inicializado.");
}

/**
 * Guarda el estado actual en localStorage.
 */
function guardar() {
    try {
        localStorage.setItem('spreadsheetState', JSON.stringify(estado));
        console.log("Estado guardado exitosamente.");
    } catch (e) {
        console.error("Error al guardar el estado:", e);
    }
}

/**
 * Obtiene el valor de una celda específica del objeto estado.
 * @param {string} cellId - ID de la celda (ej: 'A3').
 * @returns {string} El contenido de la celda o vacío si no existe.
 */
function getCellValue(cellId) {
    return estado[cellId] === undefined ? '' : estado[cellId];
}

/**
 * Calcula la suma de un rango de celdas (ej: 'A1:B5'). Ignora fórmulas.
 * @param {string} rangeString - Rango en formato A1:B2.
 * @returns {number|string} La suma o el texto del error si no es numérico.
 */
function calculateSum(rangeString) {
    if (!rangeString || !rangeString.includes(':')) return '';

    const [startCellId, endCellId] = rangeString.split(':');
    let sum = 0;
    let count = 0;

    // Helper para obtener coordenadas de una celda ID (ej: A1 -> {row: 1, col: 'A'})
    const getCoords = (cellId) => {
        if (!cellId || cellId.length < 2) return null;
        const rowStr = cellId.slice(-1);
        const colChar = cellId.slice(0, -1);
        let colIndex = 0;
        for (let i = 65; i <= 90; i++) { // A=65, J=74
            if (colChar.includes(String.fromCharCode(i))) {
                colIndex = i - 65;
                break;
            }
        }
        return { row: parseInt(rowStr), col: colIndex };
    };

    const startCoords = getCoords(startCellId);
    const endCoords = getCoords(endCellId);

    if (!startCoords || !endCoords) return 'Error';

    const startRow = startCoords.row;
    const startCol = Math.min(startCoords.col, endCoords.col);
    const endRow = Math.max(startCoords.row, endCoords.row);
    const endCol = Math.max(startCoords.col, endCoords.col);

    for (let r = startRow; r <= endRow; r++) {
        for (let c = startCol; c <= endCol; c++) {
            const cellId = String.fromCharCode(65 + c) + r;
            const value = getCellValue(cellId);

            if (!isNaN(parseFloat(value)) && isFinite(value)) {
                sum += parseFloat(value);
                count++;
            }
        }
    }

    return count > 0 ? sum.toFixed(2) : '';
}


/**
 * Evalúa una fórmula matemática simple (ej: =A1+B2). Soporta SUM y referencias.
 * @param {string} formulaString - La fórmula a evaluar.
 * @returns {string} El resultado formateado o el texto de error.
 */
function evaluateFormula(formulaString) {
    if (!formulaString || !formulaString.startsWith('=')) return formulaString;

    let expression = formulaString.substring(1).trim();

    // 1. Reemplazar referencias de celda por sus valores actuales
    const cellRegex = /([A-Z]+[0-9]+)/g; // Coincide con A1, B20, etc.
    expression = expression.replace(cellRegex, (match) => {
        const value = getCellValue(match);
        // Si el valor es un número y no una fórmula, lo usamos directamente
        if (!isNaN(parseFloat(value)) && isFinite(value) && !value.startsWith('=')) {
            return parseFloat(value).toFixed(2);
        }
        // Si es texto o fórmula compleja, lo mantenemos como string para evitar errores de eval
        return `"${value.replace(/"/g, '\\"')}"`;
    });

    // 2. Manejar la función SUM (ej: =SUM(A1:B5))
    if (expression.toUpperCase().startsWith('SUM')) {
        const matchSum = expression.match(/SUM\(([^)]+)\)/i);
        if (matchSum && matchSum[1]) {
            const range = matchSum[1].trim();
            return calculateSum(range);
        }
    }

    // 3. Evaluación de expresiones matemáticas simples usando 'eval' (PELIGROSO en apps reales, pero requerido aquí)
    try {
        // Simplificamos la evaluación para manejar solo números y operadores básicos después del reemplazo.
        let safeExpression = expression.replace(/["']/g, ''); // Eliminar comillas de string literal temporalmente

        // Solo si el resultado es puramente numérico en esta etapa (sin texto)
        if (!/[a-zA-Z]/.test(safeExpression)) {
             const result = Function('return ' + safeExpression);
             return parseFloat(result()) !== 0 ? result().toFixed(2) : '';
        }

    } catch (e) {
        console.error("Error al evaluar la fórmula:", e);
        return '#ERROR!';
    }

    // Si no se pudo resolver, devolvemos el original o un error genérico si era una fórmula
    if (formulaString && formulaString.startsWith('=')) {
         return '#FORMULA_ERROR!';
    }

    return expression; // Devolver lo que quedó sin procesar
}


/**
 * Actualiza el valor de una celda en el estado y actualiza su contenido si es necesario.
 * @param {string} cellId - ID de la celda (ej: 'A3').
 * @param {string} newValue - El nuevo valor a asignar.
 */
function actualizarCelda(cellId, newValue) {
    estado[cellId] = newValue;
}

/**
 * Limpia el contenido de una columna específica en todas las filas.
 * @param {string} columnChar - La letra de la columna (A-J).
 */
function clearColumnContent(columnChar) {
    for (let i = 1; i <= MAX_ROWS; i++) {
        const cellId = columnChar + i;
        actualizarCelda(cellId, '');
    }
}

/**
 * Renderiza todo el estado en el DOM. Debe llamarse después de cualquier cambio estructural o de datos.
 */
function render() {
    // 1. Limpiar contenido del cuerpo
    const tableBody = document.querySelector('#spreadsheetTable tbody');
    if (!tableBody) return;

    while (tableBody.firstChild) {
        tableBody.removeChild(tableBody.firstChild);
    }

    // 2. Reconstruir filas y celdas con los datos actuales del estado
    for (let i = 1; i <= MAX_ROWS; i++) {
        const row = document.createElement('tr');
        row.setAttribute('data-row', i);

        // Celda de etiqueta de fila (Row Label)
        const labelCell = document.createElement('th');
        labelCell.className = 'row-label';
        labelCell.textContent = i;
        labelCell.setAttribute('data-row-index', i); // Añadir data attribute para manejo JS

        // Agregar la celda de etiqueta al inicio de la fila (para mantener el orden visual)
        const rowLabelContainer = document.createElement('th');
        rowLabelContainer.className = 'row-label';
        rowLabelContainer.textContent = i;
        rowLabelContainer.setAttribute('data-row-index', i);

        // Las celdas de datos (A, B, C...)
        const dataCells = [];
        for (let j = 1; j <= MAX_COLS; j++) {
            const cellId = String.fromCharCode(64 + j) + i; // A1, B1...
            const td = document.createElement('td');
            td.setAttribute('data-cell', cellId);
            td.contentEditable = 'true';
            td.textContent = getCellValue(cellId) || '';
            td.dataset.row = i;
            td.dataset.col = String.fromCharCode(64 + j);
            dataCells.push(td);
        }

        // Reconstruir la fila: [Label] + [Data Cells...]
        const newRow = document.createElement('tr');
        newRow.appendChild(rowLabelContainer); // La primera celda es el label
        dataCells.forEach(cell => {
             newRow.appendChild(cell);
        });

        tableBody.appendChild(newRow);
    }
}

/**
 * Maneja los cambios de contenido en las celdas (triggerado por focusout o Enter).
 * @param {HTMLElement} target - La celda TD que ha perdido el foco.
 */
function handleCellChange(target) {
    const cellId = target.getAttribute('data-cell');
    if (!cellId) return;

    let newValue = target.textContent.trim();

    // 1. Verificar si es una fórmula (detectado por '=' al inicio del texto).
    if (newValue.startsWith('=')) {
        const formulaText = newValue;
        actualizarCelda(cellId, formulaText);

        // Evaluar la fórmula y actualizar el contenido visible con el resultado.
        const result = evaluateFormula(formulaText);
        target.textContent = result === '#ERROR!' || result === '#FORMULA_ERROR!' ? 'Error' : result;
        actualizarCelda(cellId, formulaText); // Guardamos la fórmula en estado

    } else {
        // 2. Es un valor de texto o número simple.
        actualizarCelda(cellId, newValue);
    }

    guardar(); // Siempre guardamos al finalizar la edición.
}


/**
 * Conecta los event listeners a elementos del DOM para manejar interacciones.
 */
function conectar() {
    // Usamos event delegation en el tbody para capturar eventos de todas las celdas sin añadir listeners individuales.
    const tableBody = document.querySelector('#spreadsheetTable tbody');
    if (!tableBody) return;

    // 1. Evento de pérdida de foco (blur): Se dispara al hacer clic fuera o con Tab.
    // Esto captura el cambio cuando termina la edición.
    tableBody.addEventListener('focusout', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            handleCellChange(target);
        }
    });

    // 2. Evento de pulsación de tecla (keydown): Para detectar Enter.
    tableBody.addEventListener('keydown', (e) => {
        const target = e.target;
        if (target && target.hasAttribute('contenteditable') && target.getAttribute('data-cell')) {
            // Solo procesar si se presiona Enter y no estamos en un estado de edición especial
            if (e.key === 'Enter') {
                e.preventDefault(); // Previene el salto de línea por defecto en contenteditable
                handleCellChange(target);
            }
        }
    });

    // 3. Manejo de clic en cabecera de columna (Letras A-J)
    const headerCells = document.querySelectorAll('#spreadsheetTable thead th');
    headerCells.forEach(th => {
        // Verificamos si la celda contiene una letra de columna válida (A-Z).
        const colCharMatch = th.textContent.trim().match(/^[A-Z]$/);
        if (colCharMatch) {
            th.addEventListener('click', () => {
                const columnChar = colCharMatch[0];
                // Ejecutamos la lógica de vaciado al hacer clic en la letra de la columna.
                clearColumnContent(columnChar);

                // Guardar y redibujar para que el cambio se refleje.
                guardar();
                render();
            });
        }
    });

    // 4. Manejo de clic en etiquetas de fila (Row Labels)
    const rowLabels = document.querySelectorAll('.row-label');
    rowLabels.forEach(label => {
        label.addEventListener('click', handleRowSelect);
    });
}

/**
 * Inicializa la aplicación: Cargar datos, conectar eventos y renderizar la UI.
 */
function arrancar() {
    cargar();
    conectar();
    render();
}
