```javascript
/**
 * Borra completamente una fila (estado y DOM).
 * @param {number} rowIndex - El índice de la fila (1 a 20).
 */
function deleteRow(rowIndex) {
    if (!confirm(`¿Está seguro que desea borrar la Fila ${rowIndex}? Esta acción no se puede deshacer.`)) {
        return;
    }

    // 1. Limpiar el estado de todas las celdas en esta fila (A-J, por ejemplo).
    for (let cIndex = 0; cIndex < COLS.length; cIndex++) {
        const colChar = COLS[cIndex];
        const cellId = colChar + rowIndex;
        delete estado[cellId];
    }

    // 2. Localizar y eliminar la fila del DOM (el <tr> completo).
    // Buscamos cualquier celda con data-cell que contenga el índice de la fila.
    const rowCells = document.querySelectorAll(`[data-cell*="${rowIndex}"]`);
    if (rowCells.length > 0) {
        const parentRow = rowCells[0].closest('tr');
        if (parentRow) {
            parentRow.remove();
        }
    }

    // 3. Guardar y redibujar para reflejar la eliminación estructural.
    guardar();
    render();
}
