    let cellsToSum = rangeString.replace(/;/g, ' ').replace(/,/g, ' ');

    // Si contiene rangos tipo A1:A3, lo procesamos primero
    const ranges = cellsToSum.match(/[A-Z]+\d+(?::[A-Z]+\d+)*|([A-Z]\d+)/g);
