    let menuDiv = document.createElement('div');
    menuDiv.style.position = 'fixed';
    menuDiv.style.zIndex = '1000';
    menuDiv.style.backgroundColor = '#fff';
    menuDiv.style.border = '1px solid #ccc';
    menuDiv.style.padding = '10px';
